const request = $('Inventory Webhook').first().json.body ?? {};
const productId = request.productId;
const requestedQuantity = Number(request.requestedQuantity);

if (!productId || !Number.isInteger(requestedQuantity) || requestedQuantity <= 0) {
  throw new Error('Request must include productId and a positive integer requestedQuantity.');
}

const resultItems = $('Get Product Stock').all().map(item => item.json);
let product = resultItems.length === 1 && Array.isArray(resultItems[0])
  ? resultItems[0][0]
  : resultItems[0];

if (!product || !product.id) {
  throw new Error(`Product not found: ${productId}`);
}

const availableStock = Number(product.stock_quantity ?? 0);
const reorderLevel = Number(product.reorder_level ?? 0);
const shortage = Math.max(0, requestedQuantity - availableStock);
const sufficient = shortage === 0;

// If stock is short, recommend enough to cover the shortage and restore
// the configured reorder buffer.
const recommendedReorderQuantity = sufficient
  ? 0
  : shortage + reorderLevel;

const response = {
  success: true,
  product: {
    id: product.id,
    name: product.name,
    sku: product.sku
  },
  requestedQuantity,
  availableStock,
  shortage,
  stockSufficient: sufficient,
  recommendation: sufficient
    ? {
        action: 'NO_REORDER_REQUIRED',
        quantity: 0,
        reason: 'Available stock can satisfy the requested quantity.'
      }
    : {
        action: 'REORDER',
        quantity: recommendedReorderQuantity,
        reason: `Short by ${shortage} unit(s). The recommendation also restores the reorder buffer of ${reorderLevel} unit(s).`
      }
};

return [{
  json: {
    response,
    input_data: { productId, requestedQuantity },
    output_data: response
  }
}];
